style.css:
/* Modificar o fundo e a cor do texto do corpo da página */
body {
    background-color: #f0f0f0;  /* Cor de fundo clara */
    color: #333333;  /* Cor do texto */
}

/* Mudar o fundo dos links */
a {
    color: #0066cc;  /* Cor dos links */
}

/* Mudar a cor do link quando estiver sobre ele */
a:hover {
    color: #ff6600;  /* Cor do link ao passar o mouse */
}
